def fault_effect(segment, now):
    """fq 同款 effect：无活动段（未登记或段间隙）为 N；活动段 D 为 D、
    F 按 ((now-a)//v)%2=0 相位取 D 否则 N、S 为 S。"""
    if segment is None:
        return "N"
    k, a, _, v = segment
    if k == "D":
        return "D"
    if k == "F":
        return "D" if ((now - a) // v) % 2 == 0 else "N"
    return "S"

